-- Applicant follow-up: Overdue / Stalled / Waiting on Admin / On hold made actionable.
-- Additive only and safe to run again. Existing follow-ups become kind 'contact' (unchanged).

-- 1. Thresholds (one row). No row is seeded: the API uses 7 and 14 days until Admin saves.
create table if not exists public."follow_up_settings" (
  "id" bigint generated by default as identity primary key,
  "overdue_days" smallint not null default 7,
  "stalled_days" smallint not null default 14,
  "updated_by_user_id" bigint references public."users" ("id") on delete set null,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now(),
  constraint "follow_up_settings_days_check" check ("overdue_days" between 1 and 60 and "stalled_days" > "overdue_days" and "stalled_days" <= 120)
);
alter table public."follow_up_settings" enable row level security;

-- 2. "Log follow-up" on an overdue applicant: a follow-up of kind 'overdue' with a reason and a next action date.
alter table public."follow_ups" add column if not exists "kind" text not null default 'contact';
alter table public."follow_ups" add column if not exists "reason" text;
alter table public."follow_ups" alter column "channel" drop not null;
alter table public."follow_ups" alter column "outcome" drop not null;
alter table public."follow_ups" drop constraint if exists "follow_ups_kind_check";
alter table public."follow_ups" add constraint "follow_ups_kind_check" check (
  ("kind" = 'contact' and "channel" is not null and "outcome" is not null)
  or ("kind" = 'overdue' and "followable_type" = 'applicant' and "next_follow_up_at" is not null
      and "reason" in ('waiting_documents', 'not_responding', 'rescheduled', 'still_deciding', 'other'))
);

-- 3. Reminders, holds, hold releases and closures. Append-only; shown in the applicant's Follow-up log.
create table if not exists public."applicant_follow_up_events" (
  "id" bigint generated by default as identity primary key,
  "applicant_id" bigint not null references public."applicants" ("id") on delete cascade,
  "kind" text not null,
  "user_id" bigint references public."users" ("id") on delete set null,
  "to_user_id" bigint references public."users" ("id") on delete set null,
  "message" text,
  "reason" text,
  "until_at" timestamptz,
  "snapshot" jsonb,
  "created_at" timestamptz not null default now(),
  constraint "applicant_follow_up_events_kind_check" check ("kind" in ('reminder', 'hold', 'hold_released', 'closed'))
);
create index if not exists "applicant_follow_up_events_idx" on public."applicant_follow_up_events" ("applicant_id", "kind", "created_at");
alter table public."applicant_follow_up_events" enable row level security;
drop trigger if exists "applicant_follow_up_events_append_only" on public."applicant_follow_up_events";
create trigger "applicant_follow_up_events_append_only" before update on public."applicant_follow_up_events"
  for each row execute function public.refuse_history_update();

-- 4. Hold and the close reason.
alter table public."applicants" add column if not exists "on_hold_until" timestamptz;
alter table public."applicants" add column if not exists "on_hold_reason" text;
alter table public."applicants" add column if not exists "on_hold_at" timestamptz;
alter table public."applicants" add column if not exists "on_hold_by_user_id" bigint references public."users" ("id") on delete set null;
alter table public."applicants" add column if not exists "hold_ended_at" timestamptz;
alter table public."applicants" add column if not exists "archive_reason" text;

-- The automatic alert already sent for the current overdue/stalled episode (kept apart from applicants so
-- sending an alert never changes applicants.updated_at, which the "Updated" date filter uses).
create table if not exists public."applicant_follow_up_alerts" (
  "applicant_id" bigint primary key references public."applicants" ("id") on delete cascade,
  "alert_key" text not null,
  "notified_at" timestamptz not null default now()
);
alter table public."applicant_follow_up_alerts" enable row level security;

-- 5. The "last Sales update" lookups.
create index if not exists "applicant_stage_histories_actor_idx" on public."applicant_stage_histories" ("applicant_id", "actor_role", "changed_at");
create index if not exists "follow_ups_applicant_latest_idx" on public."follow_ups" ("followable_id", "created_at") where "followable_type" = 'applicant';
